-- Level 1 – Basic SQL (1–10)

-- 1. Find the total number of orders in the dataset.

SELECT count(DISTINCT [Order ID]) as totalorders from orders$

-- 2. Calculate total Sales, total Profit and total Quantity sold.
SELECT sum(sales) as totalsales,sum(profit) as totalprofit,sum(Quantity)  as totalquantity FROM Orders$


-- 3. Find total Sales generated by each Region.
SELECT Region,sum(sales) as RegionSales FROM Orders$
GROUP BY Region
ORDER BY RegionSales DESC

-- 4. Calculate average Discount for each Sub-Category.
SELECT [Sub-Category],avg(Discount) as avgdiscount FROM Orders$
GROUP BY [Sub-Category]
ORDER BY avgdiscount ASC

-- 5. Find the top 10 customers based on total Sales.
SELECT top 10 [Customer Name],sum(sales) as totalsales FROM Orders$
GROUP BY [Customer Name]
ORDER BY totalsales DESC

-- 6. Identify all orders where Profit is negative.
SELECT DISTINCT[order id],sum(Profit) as negativeprofit FROM Orders$
GROUP BY [Order ID]
HAVING sum(Profit)<0

-- 7. Find the number of distinct customers in each Region.
SELECT Region,COUNT(DISTINCT [Customer ID]) as totalcustomer FROM  Orders$
GROUP BY Region

-- 8. Calculate total Sales by each Ship Mode.
SELECT [Ship mode] ,sum(sales) as totalsales from Orders$
GROUP BY [Ship Mode]

-- 9. Find the highest and lowest individual order Sales.
SELECT max(sales) as highestsales,min(sales) as lowetsales from orders$



-- 10. Display monthly Sales for each year.
SELECT YEAR([order date]) as year,MONTH([order date]) as month,sum(sales) as totalSales
from Orders$
GROUP BY year([order date]),month([order date])
ORDER by [year],[month]



-- Level 2 – Intermediate SQL (11–20)


-- 11. Find customers whose total Sales exceed ₹10,000.
SELECT [Customer Name],sum(sales) as totalsales FROM Orders$
GROUP BY [Customer Name]
HAVING sum(Sales)>10000
ORDER BY totalsales ASC

-- 12. Identify the top 5 most profitable Sub-Categories.
SELECT top 5 [Sub-Category],sum(sales) as totalsales FROM Orders$
GROUP BY [Sub-Category]
ORDER BY totalsales DESC



-- 13. Find customers who placed orders in multiple years.
SELECT DISTINCT [Customer Name],COUNT(DISTINCT YEAR([Order Date])) as totalyear FROM Orders$
GROUP BY [Customer Name]
HAVING COUNT(DISTINCT YEAR([Order Date]))>1

-- 14. Calculate each Region's percentage contribution to overall Sales.
SELECT Region,sum(sales) as totalsales,round(sum(sales)*100.0/(SELECT sum(Sales) as totalsales from Orders$),2) as conti FROM  orders$
GROUP BY Region

-- 15. Identify customers who generated negative total Profit.
SELECT [Customer Name],sum(Profit) as negativeprofit FROM Orders$
GROUP BY [Customer Name]
HAVING sum(Profit)<0

-- 16. Find the second-highest customer based on total Sales.
SELECT max(sales) as secondhighest FROM orders$
where sales<(
    SELECT max(sales) FROM Orders$
)

-- 17. Calculate the average number of days between Order Date and Ship Date for each Ship Mode.

SELECT round(avg(CAST(DATEDIFF(DAY, [order date],[Ship Date]) as float)),2) as avgday  FROM Orders$

-- 18. Find orders where Sales increased but Profit decreased compared with the previous order month.

WITH ct1 AS
(
    SELECT
        DATEFROMPARTS(
            YEAR([Order Date]),
            MONTH([Order Date]),
            1
        ) AS OrderMonth,
        SUM(Sales) AS TotalSales,
        SUM(Profit) AS TotalProfit
    FROM Orders$
    GROUP BY
        YEAR([Order Date]),
        MONTH([Order Date])
),
ct2 AS
(
    SELECT *,
        LAG(TotalSales) OVER(ORDER BY OrderMonth) AS PrevSales,
        LAG(TotalProfit) OVER(ORDER BY OrderMonth) AS PrevProfit
    FROM ct1
)
SELECT *
FROM ct2
WHERE TotalSales > PrevSales
  AND TotalProfit < PrevProfit;



-- 19. Identify customers whose latest year's Sales are higher than their previous year's Sales.

WITH ct1 AS
(
    SELECT
        YEAR([Order Date]) AS OrderYear,
        [Customer Name],
        SUM(Sales) AS TotalSales
    FROM Orders$
    GROUP BY YEAR([Order Date]), [Customer Name]
),
ct2 AS
(
    SELECT *,
        LAG(TotalSales) OVER(
            PARTITION BY [Customer Name]
            ORDER BY OrderYear
        ) AS PrevSales,
        row_number() OVER(PARTITION BY [customer name] ORDER BY orderyear DESC
        ) AS rk
    FROM ct1
)
SELECT *
FROM ct2
WHERE rk=1
  AND TotalSales > PrevSales;



