SELECT [order id], sum(Quantity) as total_quantity,
CASE 
    WHEN sum(Quantity)>=3 and sum(Quantity)<5 THEN  'small'
    WHEN sum(Quantity)>5 THEN 'bulk'
    ELSE  'low'
END fROM orders$
GROUP BY [order id]




SELECT [product id], sum(quantity) as total_quantity ,CASE 
    WHEN sum(Quantity)>3 and sum(Quantity)<5  THEN 'small'  
    WHEN sum(Quantity)>5 THEN 'bulk'
    ELSE  'small'
END as quantity_category FROM Orders$
GROUP BY [Product ID]



